import { mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import { dirname, join, resolve, sep } from 'node:path';

/** Where uploaded files live. Swappable for S3-compatible storage later (ADR-0007). */
export interface FileStorage {
  put(key: string, bytes: Uint8Array): Promise<void>;
  get(key: string): Promise<Uint8Array>;
  remove(key: string): Promise<void>;
}

export function createDiskStorage(root: string): FileStorage {
  const base = resolve(root);
  // Keys are generated by the server, but resolving defends against traversal anyway.
  const pathOf = (key: string) => {
    const full = resolve(join(base, key));
    if (!full.startsWith(base + sep)) throw new Error('Invalid storage key.');
    return full;
  };
  return {
    async put(key, bytes) {
      const full = pathOf(key);
      await mkdir(dirname(full), { recursive: true, mode: 0o750 });
      await writeFile(full, bytes, { flag: 'wx', mode: 0o640 });
    },
    get: async (key) => new Uint8Array(await readFile(pathOf(key))),
    remove: async (key) => rm(pathOf(key), { force: true }),
  };
}
